'use strict';
const {sessionTokenHash}=require('./admin-auth');
const {resolvePublicProperty}=require('./public-property-routing');
const {fail}=require('./room-gallery-store');
async function readBody(request,limit) {
  const parts=[];let size=0;
  for await(const part of request){size+=part.length;if(size>limit)fail(413,'上傳內容太大');parts.push(part);}
  return Buffer.concat(parts);
}
function createRoomGalleryRoutes({getStore,persistence,customerSettings,publicBaseUrl,sendData}) {
  const origin=new URL(publicBaseUrl).origin,uploads=new Map();let inFlight=0;
  return async(request,response,url)=>{
    const publicPath=url.pathname==='/api/public/room-gallery';
    const match=/^\/api\/room-gallery\/([^/]+)(?:\/([^/]+))?$/.exec(url.pathname);
    if(!publicPath&&!match)return false;
    response.setHeader('cache-control','no-store');response.setHeader('x-content-type-options','nosniff');
    if(publicPath){
      if(request.method!=='GET')fail(405,'不支援此操作');
      const property=resolvePublicProperty(await customerSettings.listProperties(),url.searchParams.get('slug'));
      if(!property)fail(404,'此查房連結無效');
      const roomId=url.searchParams.get('roomId');if(!roomId||roomId.length>200)fail(400,'請選擇房型');
      sendData(response,{items:await(await getStore()).list(property.propertyId,roomId,{publicOnly:true})});return true;
    }
    const cookie=String(request.headers.cookie||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('nephi_admin_session='));
    const session=cookie?await persistence.getAdminSession(sessionTokenHash(cookie.slice('nephi_admin_session='.length))):null;
    if(!session)fail(401,'請先登入');
    const propertyId=session.propertyId;
    if(!propertyId)fail(409,'請先選擇旅宿');
    if(!Array.isArray(session.properties)||!session.properties.some(x=>x.propertyId===propertyId))fail(403,'無權管理此旅宿');
    for(const field of ['propertyId','customerId'])if(url.searchParams.has(field)&&url.searchParams.get(field)!==propertyId)fail(403,'旅宿已切換，請重新整理');
    if(request.method!=='GET'&&request.headers.origin!==origin)fail(403,'請從業者後台操作');
    let roomId,action;try{roomId=decodeURIComponent(match[1]);action=match[2]?decodeURIComponent(match[2]):'';}catch{fail(400,'網址格式不正確');}
    if(!roomId||roomId.length>200)fail(400,'請選擇房型');
    const store=await getStore();
    if(request.method==='GET'&&!action){sendData(response,{items:await store.list(propertyId,roomId)});return true;}
    if(request.method==='DELETE'&&action&&action!=='order'){
      if(!/^[A-Za-z0-9_-]{32}$/.test(action))fail(400,'照片格式不正確');
      sendData(response,{items:await store.remove(propertyId,roomId,action)});return true;
    }
    if(request.method==='PUT'&&action==='order'){
      if(String(request.headers['content-type']||'').split(';')[0].trim()!=='application/json')fail(415,'排序格式不正確');
      const body=await readBody(request,8192);let data;try{data=JSON.parse(body.toString('utf8'));}catch{fail(400,'排序格式不正確');}
      if(!data||typeof data!=='object'||Object.keys(data).some(x=>x!=='photoIds'))fail(400,'排序格式不正確');
      sendData(response,{items:await store.reorder(propertyId,roomId,data.photoIds)});return true;
    }
    if(request.method==='POST'&&!action){
      if(!['image/jpeg','image/png'].includes(String(request.headers['content-type']||'').split(';')[0].trim().toLowerCase()))fail(415,'請選擇 JPG 或 PNG 圖片');
      const now=Date.now();for(const [id,entry] of uploads)if(now-entry.start>=600000)uploads.delete(id);
      if(!uploads.has(propertyId)){if(uploads.size>=1000)fail(429,'請稍候再上傳');uploads.set(propertyId,{start:now,count:0});}
      const entry=uploads.get(propertyId);if(entry.count>=60||inFlight>=2)fail(429,'上傳較頻繁，請稍候再試');entry.count++;inFlight++;
      try{sendData(response,{items:await store.add(propertyId,roomId,await readBody(request,8*1024*1024))},201);}finally{inFlight--;}
      return true;
    }
    fail(405,'不支援此操作');
  };
}
module.exports={createRoomGalleryRoutes};

'use strict';
const {fail,createRoomGalleryStore}=require('./room-gallery-store');
const {readRoomGalleryConfig,createRoomGalleryR2}=require('./room-gallery-r2');
function createRoomGalleryRuntime({databaseUrl,env=process.env}) {
  let pending=null,db=null,storage=null;
  return {
    async getStore(){
      const config=readRoomGalleryConfig(env);
      if(!databaseUrl||!config)fail(503,'房間照片尚未啟用');
      if(!pending)pending=(async()=>{
        storage=createRoomGalleryR2(config);
        db=await require('./providers/postgres-client').openPostgres({kind:'pg',databaseUrl});
        return createRoomGalleryStore({db,storage});
      })().catch(error=>{pending=null;storage?.close();storage=null;throw error;});
      return pending;
    },
    async close(){if(pending)await pending.catch(()=>{});if(db)await db.close();storage?.close();}
  };
}
module.exports={createRoomGalleryRuntime};

'use strict';
const crypto = require('node:crypto');
const {sanitizeImage} = require('./property-image-store');
const {AppError} = require('./mvp-service');
function fail(status,message) {throw new AppError(status,'ROOM_GALLERY_ERROR',message);}
function createRoomGalleryStore({db,storage,report=code=>console.error(JSON.stringify({scope:'room-gallery',code}))}) {
  async function lockRoom(tx,propertyId,roomId) {
    if(typeof roomId!=='string'||!roomId||roomId.length>200)fail(404,'找不到此房型');
    const r=await tx.query('SELECT room_id FROM room_types WHERE property_id=$1 AND room_id=$2 FOR UPDATE',[propertyId,roomId]);
    if(!r.rows.length)fail(404,'找不到此房型');
  }
  function metadata(r) {
    return {id:r.photo_id,position:r.position,ready:r.ready,originalUrl:r.ready?storage.url(r.original_key):null,previewUrl:r.ready?storage.url(r.preview_key):null};
  }
  async function list(propertyId,roomId,{publicOnly=false}={}) {
    const r=await db.query(`SELECT g.* FROM room_gallery_photos g JOIN room_types r ON r.property_id=g.property_id AND r.room_id=g.room_id WHERE g.property_id=$1 AND g.room_id=$2 ${publicOnly?'AND r.enabled=true AND g.ready=true':''} ORDER BY g.position,g.photo_id LIMIT 10`,[propertyId,roomId]);
    return r.rows.map(metadata);
  }
  async function remove(propertyId,roomId,photoId) {
    // Hide first: if object deletion fails the owner can retry, but guests never
    // receive a partly deleted pair. Metadata retains keys until both are gone.
    const hidden=await db.query('UPDATE room_gallery_photos SET ready=false WHERE property_id=$1 AND room_id=$2 AND photo_id=$3 RETURNING photo_id',[propertyId,roomId,photoId]);
    if(!hidden.rows.length)fail(404,'找不到此照片');
    try {
      await db.transaction(async tx=>{
        const r=await tx.query('SELECT * FROM room_gallery_photos WHERE property_id=$1 AND room_id=$2 AND photo_id=$3 FOR UPDATE',[propertyId,roomId,photoId]);
        if(!r.rows.length)return;
        await storage.remove(r.rows[0].original_key);await storage.remove(r.rows[0].preview_key);
        await tx.query('DELETE FROM room_gallery_photos WHERE property_id=$1 AND room_id=$2 AND photo_id=$3',[propertyId,roomId,photoId]);
      });
    } catch {report('OBJECT_DELETE_FAILED');fail(503,'照片尚未刪除完成，請再按一次刪除');}
    return list(propertyId,roomId);
  }
  async function add(propertyId,roomId,content) {
    // Verify formal ownership before decoding bytes. Lock again for admission.
    await db.transaction(tx=>lockRoom(tx,propertyId,roomId));
    const {original,preview}=await sanitizeImage(content),id=crypto.randomBytes(24).toString('base64url');
    const originalKey=`room-photos/${id}/original.jpg`,previewKey=`room-photos/${id}/preview.jpg`;
    await db.transaction(async tx=>{
      await lockRoom(tx,propertyId,roomId);
      const r=await tx.query('SELECT count(*)::integer count,COALESCE(max(position),-1)+1 position FROM room_gallery_photos WHERE property_id=$1 AND room_id=$2',[propertyId,roomId]);
      if(r.rows[0].count>=10)fail(409,'每個房型最多可放 10 張照片');
      await tx.query('INSERT INTO room_gallery_photos(property_id,room_id,photo_id,original_key,preview_key,position) VALUES($1,$2,$3,$4,$5,$6)',[propertyId,roomId,id,originalKey,previewKey,r.rows[0].position]);
    });
    try {
      await db.transaction(async tx=>{
        await lockRoom(tx,propertyId,roomId);
        const r=await tx.query('SELECT photo_id FROM room_gallery_photos WHERE property_id=$1 AND room_id=$2 AND photo_id=$3 FOR UPDATE',[propertyId,roomId,id]);
        if(!r.rows.length)fail(409,'照片已被刪除，請重新上傳');
        await storage.put(originalKey,original);await storage.put(previewKey,preview);
        await tx.query('UPDATE room_gallery_photos SET ready=true WHERE property_id=$1 AND room_id=$2 AND photo_id=$3',[propertyId,roomId,id]);
      });
    } catch {
      report('OBJECT_UPLOAD_FAILED');
      try {await remove(propertyId,roomId,id);}catch {report('OBJECT_CLEANUP_PENDING');}
      fail(503,'照片上傳未完成，請重新整理後再試；未完成的照片可刪除');
    }
    return list(propertyId,roomId);
  }
  async function reorder(propertyId,roomId,photoIds) {
    if(!Array.isArray(photoIds)||photoIds.length>10||new Set(photoIds).size!==photoIds.length||photoIds.some(x=>typeof x!=='string'||! /^[A-Za-z0-9_-]{32}$/.test(x)))fail(400,'照片排序格式不正確');
    await db.transaction(async tx=>{
      await lockRoom(tx,propertyId,roomId);
      const r=await tx.query('SELECT photo_id FROM room_gallery_photos WHERE property_id=$1 AND room_id=$2',[propertyId,roomId]);
      if(r.rows.length!==photoIds.length||r.rows.some(x=>!photoIds.includes(x.photo_id)))fail(409,'照片已變更，請重新整理後再排序');
      for(let i=0;i<photoIds.length;i++)await tx.query('UPDATE room_gallery_photos SET position=$4 WHERE property_id=$1 AND room_id=$2 AND photo_id=$3',[propertyId,roomId,photoIds[i],i]);
    });
    return list(propertyId,roomId);
  }
  return {list,add,remove,reorder};
}
module.exports={createRoomGalleryStore,fail};

'use strict';
const {fail}=require('./room-gallery-store');
function readRoomGalleryConfig(env=process.env) {
  const config={accountId:env.ROOM_GALLERY_R2_ACCOUNT_ID,bucket:env.ROOM_GALLERY_R2_BUCKET,accessKeyId:env.ROOM_GALLERY_R2_ACCESS_KEY_ID,secretAccessKey:env.ROOM_GALLERY_R2_SECRET_ACCESS_KEY,publicBaseUrl:env.ROOM_GALLERY_PUBLIC_BASE_URL};
  return Object.values(config).every(x=>typeof x==='string'&&x.trim())?config:null;
}
function createRoomGalleryR2(config,injectedClient) {
  let base;
  try {base=new URL(config.publicBaseUrl);} catch {fail(503,'房間照片尚未啟用');}
  if(base.protocol!=='https:'||base.username||base.password||base.search||base.hash||base.pathname!=='/'||base.hostname.endsWith('.r2.dev')||base.hostname.endsWith('.r2.cloudflarestorage.com'))fail(503,'房間照片需使用正式 HTTPS 圖片網域');
  if(!/^[a-f0-9]{32}$/.test(config.accountId)||! /^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$/.test(config.bucket)||!config.accessKeyId||!config.secretAccessKey)fail(503,'房間照片尚未啟用');
  const {S3Client,PutObjectCommand,DeleteObjectCommand}=require('@aws-sdk/client-s3');
  const client=injectedClient||new S3Client({region:'auto',endpoint:`https://${config.accountId}.r2.cloudflarestorage.com`,credentials:{accessKeyId:config.accessKeyId,secretAccessKey:config.secretAccessKey},maxAttempts:1});
  function key(value){if(typeof value!=='string'||! /^room-photos\/[A-Za-z0-9_-]{32}\/(original|preview)\.jpg$/.test(value))fail(400,'圖片位置不正確');return value;}
  return {
    url:value=>`${base.origin}/${key(value)}`,
    async put(value,body){await client.send(new PutObjectCommand({Bucket:config.bucket,Key:key(value),Body:body,ContentType:'image/jpeg',CacheControl:'no-store'}),{abortSignal:AbortSignal.timeout(30000)});},
    async remove(value){await client.send(new DeleteObjectCommand({Bucket:config.bucket,Key:key(value)}),{abortSignal:AbortSignal.timeout(30000)});},
    close(){client.destroy?.();}
  };
}
module.exports={createRoomGalleryR2,readRoomGalleryConfig};
